-- Match names as well as known IDs so rerunning under a fresh backup does not duplicate admin entries.
update incoming_menu s set id=m.id from public.menu_items m where lower(trim(m.name))=lower(trim(s.name));
insert into public.menu_items(id,name,category,diet,price,"portionType","pricesJSON",image,description,available)
select id,name,category,diet,price,case when portions is null then 'single' else 'multi' end,portions,'assets/newform_logo.png','',true from incoming_menu
on conflict(id) do update set category=excluded.category,price=excluded.price,"portionType"=excluded."portionType","pricesJSON"=excluded."pricesJSON";
do $$ begin
if (select count(*) from incoming_menu) <> 138 then raise exception 'Unexpected import count'; end if;
if exists(select 1 from incoming_menu s left join public.menu_items m on m.id=s.id where m.id is null or m.price is distinct from s.price or m."pricesJSON" is distinct from s.portions) then raise exception 'Import verification failed'; end if;
end $$;
commit;
select count(*) as total_dishes from public.menu_items;

